from lib import *
S = SS('t20')
steps = [
    step("订单状态机:CREATED → PAID 或 CANCELLED,PAID → SHIPPED 或 REFUNDED,SHIPPED → DELIVERED,DELIVERED、CANCELLED、REFUNDED 是终态,共 5 条合法流转。对 6 个状态各试 6 个目标状态(36 个组合):朴素写法 UPDATE SET status = ? 接受了 30 条不同状态之间的流转,其中 25 条是非法的(比如 CANCELLED → CREATED、CANCELLED → PAID);带源状态条件的写法(WHERE status IN 允许的源状态)只接受 5 条,全是合法的,没有漏掉也没有放过。", t=tl(S(1)), mark=lidx(S(1), '朴素写法接受了 30 条'), done=lidx(S(1), '带源状态条件'), b=bars([['合法的流转', 5, '5'], ['朴素写法接受的流转', 30, '30(其中 25 条非法)'], ['带源状态条件接受的流转', 5, '5(0 条非法)']], 30, done=[0, 2], mark=[1]), kv=KV([['朴素写法', '接受 30 条,25 条非法'], ['带源状态条件', '只接受 5 条合法流转'], ['做法', '把“从哪个状态来”放进 WHERE']], ['做法'])),
    step("并发的支付回调和用户取消抢同一个 CREATED 订单(1000 个订单,两个线程过屏障后同时动手),流转成功的一方要触发副作用:支付记一笔 PAYMENT_CAPTURED,取消记一笔 STOCK_RELEASED。先读状态、是 CREATED 就改并触发副作用:1000 个订单全部既收了款又释放了库存(矛盾),最终订单状态是 PAID 494、CANCELLED 506——两个线程都读到了 CREATED。条件 UPDATE(WHERE status = 'CREATED'),影响 1 行才触发副作用:469 个只收款、531 个只释放库存,矛盾 0 个。(为了让窗口足够宽,读与写之间加了一小段延迟,见文末说明。)", t=tl(S(2)), mark=lidx(S(2), '先读状态,是 CREATED'), done=lidx(S(2), '条件 UPDATE'), b=bars([['先读后写:既收款又释放库存', 1000, '1000 / 1000'], ['条件 UPDATE:既收款又释放库存', 0, '0 / 1000'], ['条件 UPDATE:只收款', 469, '469'], ['条件 UPDATE:只释放库存', 531, '531']], 1000, mark=[0], done=[1], cur=[2, 3]), kv=KV([['读后写', '两边都读到 CREATED,各触发副作用'], ['条件 UPDATE', '只有抢到流转的一方触发副作用'], ['矛盾', '1000 → 0']], ['矛盾'])),
    step("重复的支付回调(每个订单收到 3 次,500 个订单共 1500 次)。盲写 PAID 并且每次都触发副作用:1500 次全部回复成功,收款副作用总数 1500,500 个订单全部被收了多次款。条件 UPDATE(WHERE status = 'CREATED'),已经是 PAID 就幂等地当作成功、不再触发副作用:1500 次全部回复成功(回调方永远得到成功,不会因为重试而报错),收款副作用总数 500,被收多次款的订单 0 个。幂等 = 对调用方每次都成功,对世界只改一次。", t=tl(S(3)), mark=lidx(S(3), '盲写 PAID'), done=lidx(S(3), '条件 UPDATE + 已是 PAID'), b=bars([['盲写:收款副作用总数', 1500, '1500(应为 500)'], ['条件 UPDATE:收款副作用总数', 500, '500'], ['盲写:被收了多次款的订单', 500, '500'], ['条件 UPDATE:被收了多次款的订单', 0, '0']], 1500, mark=[0, 2], done=[1, 3]), kv=KV([['回调方', '每次都收到成功'], ['副作用', '只触发一次'], ['做法', '已经是目标状态就直接返回成功']], ['做法'])),
    step("流转日志:每次流转在同一个事务里追加 order_events(seq = version + 1,(order_id, seq) 唯一)。500 个订单、2 万次目标状态随机的尝试之后:只有 version 乐观锁、不检查流转合法性:接受了 20000 次,日志重放得到的状态等于当前状态的订单 500 / 500,seq 断档 0,但日志里有 17098 条非法流转。version 乐观锁加检查流转合法:接受 865 次、拒绝 19135 次,重放一致 500 / 500,断档 0,日志里的非法流转 0 条。version 保证每次流转看到的是最新状态、日志不断档;“这个流转合法吗”是另一件事,要靠状态机本身检查。", t=tl(S(4)), mark=lidx(S(4), '只有 version 乐观锁'), done=lidx(S(4), 'version 乐观锁 + 检查流转合法'), b=bars([['不检查:日志里的非法流转', 17098, '17098'], ['检查流转合法:日志里的非法流转', 0, '0'], ['两种:日志重放一致的订单', 500, '500 / 500']], 17100, mark=[0], done=[1, 2]), kv=KV([['version', '保证最新状态、seq 不断档'], ['合法性检查', '日志里非法流转 17098 → 0'], ['重放', '两种都是 500 / 500']], ['合法性检查'])),
    step("状态机放在应用里还是数据库里。另一个写入方(运维脚本、别的服务)绕过应用直接 UPDATE:没有触发器时,把已送达(DELIVERED)的订单改成 CREATED,受影响行数 1,订单真的“回到”了待支付。加上 BEFORE UPDATE 触发器(只允许那 5 条合法流转)之后,同一条 UPDATE 被数据库拒绝(错误 1644 illegal order status transition);同状态再写一次(DELIVERED → DELIVERED)仍然允许;合法的 CREATED → PAID 通过。触发器的代价:对不改 status 的 UPDATE,中位数 84 µs 对 85 µs,几乎没有差别。只有数据库里的约束才拦得住绕过应用的写入方。", t=tl(S(5)), mark=lidx(S(5), '没有触发器', '有触发器'), done=lidx(S(5), '合法的流转 CREATED → PAID', '触发器的代价'), b=bars([['无触发器:非法 UPDATE 受影响行数', 1, '1(通过了)'], ['有触发器:非法 UPDATE 受影响行数', 0, '0(被拒绝)'], ['无触发器 UPDATE µs', 84, '84'], ['有触发器 UPDATE µs', 85, '85']], 90, mark=[0], done=[1], cur=[2, 3]), kv=KV([['无触发器', '绕过应用的 UPDATE 能把状态改回去'], ['有触发器', '数据库拒绝非法流转'], ['代价', '84 µs → 85 µs']], ['有触发器'])),
]
A = mkartt('t20', 20, '分布式事务,订单状态机,并发更新,幂等,MySQL,触发器,真实验证,动画演示',
    '实测订单状态机:朴素 UPDATE 接受 30 条流转(25 条非法),带源状态条件只接受 5 条合法的;并发的支付与取消 1000 单读后写全部矛盾,条件 UPDATE 0 个;重复回调 1500 次只触发 500 次副作用;随机 2 万次尝试日志重放全部一致;触发器拦住绕过应用的非法 UPDATE。',
    '订单从创建到完成要经过一串状态,多个服务、多种事件都在改它。怎么保证只发生合法的流转?支付回调和取消同时到怎么办?重复的回调怎么处理?流转日志能不能还原状态?状态机该放在应用里还是数据库里?这篇用真实的 MySQL 逐个验证。',
    [('25 / 30', '朴素 UPDATE SET status = ? 接受的 30 条流转里,非法的有多少(带源状态条件的 0 条)'), ('1000 → 0', '并发的支付与取消 1000 单里,既收款又释放库存的矛盾单数:先读后写 → 条件 UPDATE'), ('1500 → 500', '每单 3 次重复的支付回调,收款副作用总数:盲写 → 条件 UPDATE 加幂等返回')],
    [('流转表', '<p>把允许的来源状态放进 UPDATE 的 WHERE,非法流转直接影响 0 行。</p>'),
     ('并发流转', '<p>先读后写会让支付与取消同时成功、副作用矛盾;条件 UPDATE 只让抢到流转的一方触发副作用。</p>'),
     ('重复回调', '<p>已是目标状态就直接成功返回,不再触发副作用:对调用方每次成功,对世界只改一次。</p>'),
     ('流转日志', '<p>同一个事务里追加事件,seq 用 version + 1;重放得到当前状态,但合法性需要另外检查。</p>'),
     ('数据库里的约束', '<p>别的写入方绕过应用时,只有触发器之类的数据库约束拦得住,代价很小。</p>')],
    steps,
    [ENV_T + '。本篇用一个 MySQL 26.7.0 实例(orders、order_events、effects 三张表),PyMySQL;并发抢占用线程 + 屏障;第二节“先读后写”里在读与写之间加了 0.5 ms 的延迟使竞争窗口足够宽;第四节的 2 万次随机尝试用固定种子',
     '没有验证:多个状态字段 / 子状态的组合爆炸;事件溯源(完全以事件为准)的实现;触发器在高并发、批量更新下的开销(只测了不改 status 的单行更新);状态机放在 ORM 或工作流引擎里的做法;分布式场景下流转与消息发布的原子性(见第 11 篇)'],
    '订单状态机')
